import sys
import heapq

def main():
    input = sys.stdin.buffer.readline

    N, M, X = map(int, input().split())

    adj = [[[] for _ in range(N)], [[] for _ in range(N)]]
    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        adj[0][u].append(v)
        adj[1][v].append(u)

    INF = 10**30
    dist = [[INF] * N for _ in range(2)]
    dist[0][0] = 0

    pq = [(0, 0, 0)]  # cost, parity, vertex

    while pq:
        d, p, v = heapq.heappop(pq)
        if d != dist[p][v]:
            continue

        if v == N - 1:
            print(d)
            return

        for to in adj[p][v]:
            nd = d + 1
            if nd < dist[p][to]:
                dist[p][to] = nd
                heapq.heappush(pq, (nd, p, to))

        np = 1 - p
        nd = d + X
        if nd < dist[np][v]:
            dist[np][v] = nd
            heapq.heappush(pq, (nd, np, v))

if __name__ == "__main__":
    main()
